CREATE TABLE public.habits (graph_style text CHECK (graph_style IS NULL OR (graph_style = ANY (ARRAY['progress'::text, 'bar'::text, 'line'::text, 'heatmap'::text, 'streak'::text]))), tracking_method text DEFAULT 'boolean'::text CHECK (tracking_method = ANY (ARRAY['boolean'::text, 'quantity'::text, 'duration'::text, 'rating'::text])), reminder_offset integer, location_reminders jsonb DEFAULT '[]'::jsonb, goal_id uuid, id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamp with time zone DEFAULT now(), user_id uuid NOT NULL, name text NOT NULL, category text NOT NULL, icon text, duration_minutes integer CHECK (duration_minutes IS NULL OR duration_minutes >= 0), start_time text, end_time text, target_date timestamp with time zone, is_goal boolean DEFAULT false, deleted_at timestamp with time zone, updated_at timestamp with time zone DEFAULT now(), description text, task_days jsonb DEFAULT '["mon", "tue", "wed", "thu", "fri", "sat", "sun"]'::jsonb, reminders jsonb DEFAULT '[]'::jsonb, start_date date, end_date date, type text DEFAULT 'build'::text, color text DEFAULT '#6B46C1'::text, goal_period text DEFAULT 'daily'::text, goal_value integer DEFAULT 1 CHECK (goal_value >= 0), unit text DEFAULT 'count'::text, chart_type text DEFAULT 'bar'::text, is_archived boolean DEFAULT false, show_memo boolean DEFAULT false, frequency text, week_interval integer DEFAULT 1 CHECK (week_interval IS NULL OR week_interval >= 1), time_of_day text, CONSTRAINT habits_pkey PRIMARY KEY (id), CONSTRAINT habits_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id), CONSTRAINT habits_goal_id_fkey FOREIGN KEY (goal_id) REFERENCES public.habits(id));
CREATE TABLE public.habit_completions (memo text, user_id uuid NOT NULL, habit_id uuid NOT NULL, date date NOT NULL, id uuid NOT NULL DEFAULT gen_random_uuid(), completed boolean DEFAULT true, created_at timestamp with time zone DEFAULT now(), deleted_at timestamp with time zone, updated_at timestamp with time zone DEFAULT now(), value integer DEFAULT 0, CONSTRAINT habit_completions_pkey PRIMARY KEY (id), CONSTRAINT habit_completions_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id), CONSTRAINT habit_completions_habit_id_fkey FOREIGN KEY (habit_id) REFERENCES public.habits(id));
CREATE TABLE public.profiles (id uuid NOT NULL, username text UNIQUE, email text, avatar_url text, push_token text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), CONSTRAINT profiles_pkey PRIMARY KEY (id), CONSTRAINT profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id));
CREATE TABLE public.friendships (user_id uuid, friend_id uuid, id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), deleted_at timestamp with time zone, CONSTRAINT friendships_pkey PRIMARY KEY (id), CONSTRAINT friendships_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.profiles(id), CONSTRAINT friendships_friend_id_fkey FOREIGN KEY (friend_id) REFERENCES public.profiles(id));
CREATE TABLE public.friend_requests (from_user_id uuid, to_user_id uuid, id uuid NOT NULL DEFAULT gen_random_uuid(), status text DEFAULT 'pending'::text CHECK (status = ANY (ARRAY['pending'::text, 'accepted'::text, 'declined'::text])), created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), deleted_at timestamp with time zone, CONSTRAINT friend_requests_pkey PRIMARY KEY (id), CONSTRAINT friend_requests_from_user_id_fkey FOREIGN KEY (from_user_id) REFERENCES public.profiles(id), CONSTRAINT friend_requests_to_user_id_fkey FOREIGN KEY (to_user_id) REFERENCES public.profiles(id));
CREATE TABLE public.shared_habits (status text DEFAULT 'pending'::text CHECK (status = ANY (ARRAY['pending'::text, 'accepted'::text, 'declined'::text])), habit_id uuid, owner_id uuid, shared_with_id uuid, id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), deleted_at timestamp with time zone, CONSTRAINT shared_habits_pkey PRIMARY KEY (id), CONSTRAINT shared_habits_habit_id_fkey FOREIGN KEY (habit_id) REFERENCES public.habits(id), CONSTRAINT shared_habits_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES public.profiles(id), CONSTRAINT shared_habits_shared_with_id_fkey FOREIGN KEY (shared_with_id) REFERENCES public.profiles(id));
CREATE TABLE public.notifications (user_id uuid, from_user_id uuid, type text, title text, body text, id uuid NOT NULL DEFAULT uuid_generate_v4(), read boolean DEFAULT false, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), deleted_at timestamp with time zone, CONSTRAINT notifications_pkey PRIMARY KEY (id), CONSTRAINT notifications_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.profiles(id), CONSTRAINT notifications_from_user_id_fkey FOREIGN KEY (from_user_id) REFERENCES public.profiles(id));
CREATE TABLE public.integrations (user_id uuid, service_name character varying NOT NULL, access_token_encrypted text, refresh_token_encrypted text, token_expiry timestamp with time zone, last_sync timestamp with time zone, id uuid NOT NULL DEFAULT gen_random_uuid(), is_connected boolean DEFAULT false, sync_status character varying DEFAULT 'idle'::character varying, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), CONSTRAINT integrations_pkey PRIMARY KEY (id), CONSTRAINT integrations_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id));
CREATE TABLE public.synced_activities (integration_id uuid, habit_id uuid, external_id character varying, activity_type character varying, data jsonb, id uuid NOT NULL DEFAULT gen_random_uuid(), synced_at timestamp with time zone DEFAULT now(), CONSTRAINT synced_activities_pkey PRIMARY KEY (id), CONSTRAINT synced_activities_integration_id_fkey FOREIGN KEY (integration_id) REFERENCES public.integrations(id), CONSTRAINT synced_activities_habit_id_fkey FOREIGN KEY (habit_id) REFERENCES public.habits(id));
CREATE TABLE public.shared_goals (goal_id uuid, owner_id uuid, shared_with_id uuid, id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamp with time zone DEFAULT now(), status text DEFAULT 'pending'::text CHECK (status = ANY (ARRAY['pending'::text, 'accepted'::text, 'declined'::text])), updated_at timestamp with time zone DEFAULT now(), deleted_at timestamp with time zone, CONSTRAINT shared_goals_pkey PRIMARY KEY (id), CONSTRAINT shared_goals_goal_id_fkey FOREIGN KEY (goal_id) REFERENCES public.habits(id), CONSTRAINT shared_goals_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES public.profiles(id), CONSTRAINT shared_goals_shared_with_id_fkey FOREIGN KEY (shared_with_id) REFERENCES public.profiles(id));
